/// <summary>
/// method to set parameter of use destination
/// </summary>
/// <param name = "_usePrintDestination">NoYes</param>
/// <returns>NoYes</returns>
[DataMember, SysOperationLabel(literalStr('Use print destination')), SysOperationHelpText(literalStr('Use print destination for the report')),
    SysOperationDisplayOrder('1')]
public NoYes parmRetentionDays(NoYes _usePrintDestination = usePrintDestination)
{
    usePrintDestination = _usePrintDestination;
    return usePrintDestination;
}
